Le composant est monté tout en haut de l'arbre React (dans app/_layout.tsx) et écoute la route active ainsi que le store du Browser.
// components/ai/FloatingAiAssistant.tsx
import React, { useState } from 'react';
import { View, TouchableOpacity, StyleSheet, Modal } from 'react-native';
import { usePathname } from 'expo-router';
import { useAiStore } from '@/stores/useAiStore';
import { useBrowserStore } from '@/stores/useBrowserStore';
import { useWalletStore } from '@/stores/useWalletStore';
import { AiChatModal } from './AiChatModal';

export function FloatingAiAssistant() {
  const { isEnabled } = useAiStore();
  const [isOpen, setIsOpen] = useState(false);
  const pathname = usePathname();

  // Récupération dynamique des contextes
  const activeUrl = useBrowserStore((s) => s.currentUrl);
  const activeDappTitle = useBrowserStore((s) => s.currentTitle);
  const { tokens, totalBalanceUsd } = useWalletStore();

  // Ne rien afficher si l'IA n'est pas activée par l'utilisateur
  if (!isEnabled) return null;

  const getContextPayload = () => {
    if (pathname.includes('browser')) {
      return {
        screen: 'browser',
        url: activeUrl,
        title: activeDappTitle,
      };
    }
    if (pathname.includes('markets')) {
      return {
        screen: 'markets',
      };
    }
    return {
      screen: 'wallet',
      totalUsd: totalBalanceUsd,
      tokensSummary: tokens.map((t) => `${t.symbol}: ${t.balance} (${t.valueUsd} $)`),
    };
  };

  return (
    <>
      {/* Bulle Flottante */}
      <TouchableOpacity
        style={styles.floatingButton}
        onPress={() => setIsOpen(true)}
        activeOpacity={0.8}
      >
        <SparklesIcon size={24} color="#000" />
      </TouchableOpacity>

      {/* Modal / BottomSheet de discussion */}
      <AiChatModal
        visible={isOpen}
        onClose={() => setIsOpen(false)}
        context={getContextPayload()}
      />
    </>
  );
}

