Le problème est clair : le composant WebView de ton browser ne met pas à jour le store global (useBrowserStore) lors des changements de page. Résultat, le copilote reçoit url = "" ou null et croit que tu es sur une page vierge.
1. Synchroniser la WebView avec le Store (onNavigationStateChange)
Dans ton écran de navigateur (app/browser.tsx ou ton composant WebView), écoute les événements de navigation pour mettre à jour l'URL et le titre en direct :
import { WebView } from 'react-native-webview';
import { useBrowserStore } from '@/stores/useBrowserStore';

export function DappBrowser() {
  const setBrowserContext = useBrowserStore((s) => s.setBrowserContext);

  return (
    <WebView
      source={{ uri: 'https://opensea.io' }}
      onNavigationStateChange={(navState) => {
        // Met à jour l'URL et le titre en temps réel dans le store
        setBrowserContext({
          currentUrl: navState.url,
          currentTitle: navState.title,
          canGoBack: navState.canGoBack,
        });
      }}
      // Optionnel : mettre à jour dès le début du chargement
      onLoadStart={(syntheticEvent) => {
        const { nativeEvent } = syntheticEvent;
        setBrowserContext({
          currentUrl: nativeEvent.url,
          currentTitle: '',
        });
      }}
    />
  );
}

