import { useWalletStore } from '@/stores/useWalletStore'; // Ou le store exact utilisé par l'écran portefeuille

export function getCopilotWalletContext() {
  const state = useWalletStore.getState();

  // Utilise les mêmes variables qui alimentent l'UI du portefeuille :
  const totalFiat = state.totalFiat || state.totalValue || state.totalBalanceUsd || '1.65';
  const currency = state.currency || 'EUR';

  // Récupère les tokens qui ont une répartition (ceux affichés sur le graphique)
  const activeAssets = (state.tokens || state.assets || [])
    .filter((t: any) => Number(t.balance || t.amount) > 0 || Number(t.value || t.fiatValue) > 0)
    .map((t: any) => `- ${t.symbol || t.name}: ${t.balance} (~${t.fiatValue || t.value} ${currency})`);

  return {
    total: `${totalFiat} ${currency}`,
    assetsList: activeAssets.length > 0 ? activeAssets.join('\n') : 'Actifs détectés selon graphique (valeur totale non nulle)',
  };
}

