3. Le Dispatcheur d'Actions (ActionRouter.ts)
Quand la réponse arrive dans AiChatModal.tsx, on extrait l'action et on l'exécute automatiquement (avec fermeture fluide de la modal) :
import { router } from 'expo-router';

export function handleAiAction(responseText: string, closeModal: () => void) {
  const match = responseText.match(/<ACTION>(.*?)<\/ACTION>/s);
  if (!match) return;

  try {
    const action = JSON.parse(match[1]);
    const routeConfig = APP_ROUTES_MAP.find((r) => r.id === action.target);

    if (!routeConfig) return;

    // Fermeture propre de la modale IA avant navigation
    closeModal();

    // Redirection avec paramètres éventuels
    setTimeout(() => {
      router.push({
        pathname: routeConfig.route,
        params: action.params || {},
      });
    }, 200);
  } catch (err) {
    console.warn('[AI Router] Erreur parsing action:', err);
  }
}

