Dans la fonction qui reçoit la réponse de l'API avant de l'ajouter dans la liste des messages :
export function processAiMessage(rawResponse: string, onExecuteAction: (action: any) => void) {
  const match = rawResponse.match(/<ACTION>(.*?)<\/ACTION>/s);

  if (match) {
    try {
      const action = JSON.parse(match[1]);
      onExecuteAction(action);
    } catch (e) {
      console.warn('[AI Action] Erreur parsing JSON:', e);
    }
  }

  // Nettoie la balise pour ne pas polluer l'UI
  const cleanText = rawResponse.replace(/<ACTION>.*?<\/ACTION>/s, '').trim();
  return cleanText;
}

